for tz in UTC Asia/Tokyo America/Los_Angeles; do echo "== server TZ=$tz"; TZ=$tz node --input-type=module -e '
import { checkSms } from "./bot.mjs";
const to = (o={}) => ({ phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...o });
const m = (o={}, body="hi") => ({ kind: "marketing", body, to: to(o) });
const t = (o={}) => ({ kind: "transactional", body: "code 123456", to: to(o) });
const cases = [
  ["txn 03:00 local allowed", t(), "2026-10-23T08:00:00Z", {allowed:true,reason:null}],
  ["txn opted out", t({optedOutAt:"2026-10-01T00:00:00Z"}), "2026-10-23T15:00:00Z", {allowed:false,reason:"opted_out"}],
  ["mkt 07:59 Chicago blocked", m(), "2026-10-23T12:59:00Z", {allowed:false,reason:"outside_marketing_hours"}],
  ["mkt 08:00 Chicago allowed", m(), "2026-10-23T13:00:00Z", {allowed:true,reason:null}],
  ["mkt 20:59 Chicago allowed", m(), "2026-10-24T01:59:00Z", {allowed:true,reason:null}],
  ["mkt 21:00 Chicago blocked", m(), "2026-10-24T02:00:00Z", {allowed:false,reason:"outside_marketing_hours"}],
  ["mkt DST Nov1 08:00 CST allowed", m(), "2026-11-01T14:00:00Z", {allowed:true,reason:null}],
  ["mkt DST Nov1 07:59 CST blocked", m(), "2026-11-01T13:59:00Z", {allowed:false,reason:"outside_marketing_hours"}],
  ["mkt no consent", m({marketingConsent:false}), "2026-10-23T15:00:00Z", {allowed:false,reason:"no_marketing_consent"}],
  ["mkt opted out", m({optedOutAt:"2026-10-01T00:00:00Z"}), "2026-10-23T15:00:00Z", {allowed:false,reason:"opted_out"}],
  ["mkt bad zone", m({timeZone:"Mars/Olympus"}), "2026-10-23T15:00:00Z", {allowed:false,reason:"invalid_time_zone"}],
  ["mkt bad optedOutAt", m({optedOutAt:"yesterday"}), "2026-10-23T15:00:00Z", {allowed:false,reason:"opt_out_status_unknown"}],
  ["unknown kind", {kind:"promo",body:"x",to:to()}, "2026-10-23T15:00:00Z", {allowed:false,reason:"unknown_kind"}],
  ["bad now", t(), new Date("nope"), {allowed:false,reason:"invalid_now"}],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const d = now instanceof Date ? now : new Date(now);
  const got = checkSms(msg, d);
  const ok = got.allowed === want.allowed && got.reason === want.reason;
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
console.log(fail ? `${fail} FAILED` : "all passed");
process.exitCode = fail ? 1 : 0;
'; done

